// writeSetIndex builds a set of canonical paths from write_set for
// O(1) membership checks.
func writeSetIndex(writeSet []string) map[string]bool {
	m := make(map[string]bool, len(writeSet))
	for _, p := range writeSet {
		cp := CanonicalPath(p)
		if cp != "" {
			m[cp] = true
		}
	}
	return m
}

